using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static IDistributedApplicationTestingBuilder _appHostBuilder = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHostBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHostBuilder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(Directory.GetCurrentDirectory(), "eval-reports");

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return DiskBasedReportingConfiguration.Create(storageRootPath: path, evaluators: evaluators);
    }

